n = int(input())
vetor = list(map(int, input().split()))
vetor = [0] + vetor
resposta = 0
for i in range(1, n + 1):
	if vetor[i] > vetor[i - 1]:
		resposta += (vetor[i] - vetor[i - 1]) * (n - vetor[i] + 1)
	else:
		resposta += (vetor[i - 1] - vetor[i]) * vetor[i]
print(resposta)
